package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class StringUtils_indexOfAnyBut_TriageGen0Test {

    private static final int INDEX_NOT_FOUND = -1;

    @Test
    public void testIndexOfAnyBut_NullStr() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut(null, "abc"));
    }

    @Test
    public void testIndexOfAnyBut_EmptyStr() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("", "abc"));
    }

    @Test
    public void testIndexOfAnyBut_NullSearchChars() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("abc", null));
    }

    @Test
    public void testIndexOfAnyBut_EmptySearchChars() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("abc", ""));
    }

    @Test
    public void testIndexOfAnyBut_NoMatch() {
        // All characters in str are in searchChars
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("abc", "abcde"));
    }

    @Test
    public void testIndexOfAnyBut_MatchFoundAtStart() {
        // 'z' is not in "abc"
        assertEquals(0, StringUtils.indexOfAnyBut("zabc", "abc"));
    }

    @Test
    public void testIndexOfAnyBut_MatchFoundInMiddle() {
        // 'z' is not in "abc"
        assertEquals(2, StringUtils.indexOfAnyBut("abzc", "abc"));
    }

    @Test
    public void testIndexOfAnyBut_MatchFoundAtEnd() {
        // 'z' is not in "abc"
        assertEquals(3, StringUtils.indexOfAnyBut("abcz", "abc"));
    }

    @Test
    public void testIndexOfAnyBut_AllCharsInSearch() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("aaaaa", "a"));
    }

    /**
     * Note: The provided source code contains a logic error/bug: 
     * 'char ch2 = str.charAt(i % 1);' will always throw ArithmeticException: / by zero.
     * However, as a professional tester, I must write tests that cover the branches 
     * provided in the snippet. If the code is intended to handle High Surrogates, 
     * the modulo 1 is a bug.
     * 
     * To maximize coverage of the 'if (i + 1 < strLen && Character.isHighSurrogate(ch))' branch,
     * we use a surrogate pair.
     */
    @Test(expected = ArithmeticException.class)
    public void testIndexOfAnyBut_HighSurrogateBranch() {
        // \uD83D is a high surrogate
        String str = "\uD83D\uDE00"; 
        String searchChars = "\uD83D";
        // This will trigger: if (i + 1 < strLen && Character.isHighSurrogate(ch))
        // and then fail at: str.charAt(i % 1)
        StringUtils.indexOfAnyBut(str, searchChars);
    }

    @Test
    public void testIndexOfAnyBut_SingleCharStr() {
        assertEquals(0, StringUtils.indexOfAnyBut("a", "b"));
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("a", "a"));
    }
}
